import java.io.*;
import java.util.*;

class Solution {
    public int maxEvents(int[][] events) {
        Arrays.sort(events, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        int i = 0, day = 1, ans = 0;

        while (i < events.length || !heap.isEmpty()) {
            if (heap.isEmpty() && i < events.length && day < events[i][0]) {
                day = events[i][0];
            }
            while (i < events.length && events[i][0] <= day) {
                heap.offer(events[i][1]);
                i++;
            }
            while (!heap.isEmpty() && heap.peek() < day) {
                heap.poll();
            }
            if (!heap.isEmpty()) {
                heap.poll();
                ans++;
                day++;
            }
        }
        return ans;
    }
}

