class Solution {
public:
    int maxEvents(vector<vector<int>>& events) {
        sort(events.begin(), events.end(), [](const auto& a, const auto& b) {
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] < b[1];
        });

        priority_queue<int, vector<int>, greater<int>> pq;
        int i = 0, day = 1, ans = 0;

        while (i < (int)events.size() || !pq.empty()) {
            if (pq.empty() && i < (int)events.size() && day < events[i][0]) {
                day = events[i][0];
            }
            while (i < (int)events.size() && events[i][0] <= day) {
                pq.push(events[i][1]);
                ++i;
            }
            while (!pq.empty() && pq.top() < day) {
                pq.pop();
            }
            if (!pq.empty()) {
                pq.pop();
                ++ans;
                ++day;
            }
        }
        return ans;
    }
};

static vector<int> parseInts(const string& s) {
    vector<int> vals;
    for (size_t i = 0; i < s.size();) {
        while (i < s.size() && !isdigit((unsigned char)s[i]) && s[i] != '-') ++i;
        if (i >= s.size()) break;
        int sign = 1;
        if (s[i] == '-') { sign = -1; ++i; }
        int v = 0;
        while (i < s.size() && isdigit((unsigned char)s[i])) {
            v = v * 10 + (s[i] - '0');
            ++i;
        }
        vals.push_back(sign * v);
    }
    return vals;
}

