static int cmpEvents(const void* a, const void* b) {
    const int* ea = *(const int* const*)a;
    const int* eb = *(const int* const*)b;
    if (ea[0] != eb[0]) return (ea[0] > eb[0]) - (ea[0] < eb[0]);
    return (ea[1] > eb[1]) - (ea[1] < eb[1]);
}

static void heapPush(int* heap, int* size, int x) {
    int i = (*size)++;
    heap[i] = x;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p] <= heap[i]) break;
        int t = heap[p]; heap[p] = heap[i]; heap[i] = t;
        i = p;
    }
}

static int heapPop(int* heap, int* size) {
    int root = heap[0];
    int last = heap[--(*size)];
    if (*size == 0) return root;
    heap[0] = last;
    int i = 0;
    while (1) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < *size && heap[l] < heap[m]) m = l;
        if (r < *size && heap[r] < heap[m]) m = r;
        if (m == i) break;
        int t = heap[i]; heap[i] = heap[m]; heap[m] = t;
        i = m;
    }
    return root;
}

int maxEvents(int** events, int eventsSize, int* eventsColSize) {
    (void)eventsColSize;
    if (eventsSize == 0) return 0;

    qsort(events, (size_t)eventsSize, sizeof(int*), cmpEvents);
    int* heap = (int*)malloc((size_t)eventsSize * sizeof(int));
    int hsize = 0, i = 0, day = 1, ans = 0;

    while (i < eventsSize || hsize > 0) {
        if (hsize == 0 && i < eventsSize && day < events[i][0]) {
            day = events[i][0];
        }
        while (i < eventsSize && events[i][0] <= day) {
            heapPush(heap, &hsize, events[i][1]);
            ++i;
        }
        while (hsize > 0 && heap[0] < day) {
            (void)heapPop(heap, &hsize);
        }
        if (hsize > 0) {
            (void)heapPop(heap, &hsize);
            ++ans;
            ++day;
        }
    }

    free(heap);
    return ans;
}

